package compshare

import (
	"net"
	"testing"

	"golang.org/x/crypto/ssh"
)

func TestTOFUCallbackRecordsAndRejects(t *testing.T) {
	// Exercise the callback with deterministic fake public keys generated by
	// parsing the same authorized-key fixture twice; a mismatching key is
	// covered by the callback's fingerprint comparison in provider integration.
	store := newMemoryHostKeys()
	key, _, _, _, err := ssh.ParseAuthorizedKey([]byte("ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIB6j7s3D2v2wqG7W6X5q6dM4q9G3G9u4J5L5vQ4m8R5P test\n"))
	if err != nil {
		t.Skip(err)
	}
	cb := tofuCallback(store, endpointKey("127.0.0.1", 22))
	if err := cb("127.0.0.1:22", &net.TCPAddr{}, key); err != nil {
		t.Fatal(err)
	}
	if err := cb("127.0.0.1:22", &net.TCPAddr{}, key); err != nil {
		t.Fatal(err)
	}
	if _, ok := store.Get(endpointKey("127.0.0.1", 22)); !ok {
		t.Fatal("host key was not recorded")
	}
}
